function longestSubsequence(nums) {
  const maxValue = Math.max(...nums);
  // dp[v][d]: longest valid subsequence ending in value v whose last gap is at least d.
  const dp = Array.from({ length: maxValue + 1 }, () => new Array(maxValue + 1).fill(0));
  let best = 0;

  for (const num of nums) {
    const ending = new Array(maxValue + 1).fill(1);
    for (let prev = 1; prev <= maxValue; prev++) {
      const gap = Math.abs(num - prev);
      ending[gap] = Math.max(ending[gap], dp[prev][gap] + 1);
    }
    let longest = 0;
    for (let gap = maxValue; gap >= 0; gap--) {
      longest = Math.max(longest, ending[gap]);
      dp[num][gap] = Math.max(dp[num][gap], longest);
    }
    best = Math.max(best, dp[num][0]);
  }
  return best;
}

