function longestSubsequence(nums) {
  const n = nums.length;
  // chain[j][i]: longest valid subsequence whose last two picks are positions j < i.
  const chain = Array.from({ length: n }, () => new Array(n).fill(2));
  let best = 2;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      const last = Math.abs(nums[i] - nums[j]);
      for (let k = 0; k < j; k++) {
        if (Math.abs(nums[j] - nums[k]) >= last) chain[j][i] = Math.max(chain[j][i], chain[k][j] + 1);
      }
      best = Math.max(best, chain[j][i]);
    }
  }
  return best;
}

