function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 9);
  const top = [3, 10, 40, 300][Math.floor(rand() * 4)];
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
